## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/pancreaticMassLogic.ts`

```typescript
/**
 * Pancreatic Mass Evaluation Clinical Logic Engine
 * Based on: ASGE Guideline on EUS-Guided Tissue Acquisition (2019, 2024 Update)
 *           ACG Clinical Guideline: Diagnosis and Management of Pancreatic Cysts (2018, 2024 Update)
 *           NCCN Guidelines: Pancreatic Adenocarcinoma (2025)
 *           IAP/APA Guidelines on Intraductal Papillary Mucinous Neoplasms (2023)
 * Key decisions: Solid vs cystic mass, EUS-FNB vs FNA, molecular diagnostics,
 *                IPMN surveillance, resectability assessment
 */

export type PancreaticMassType =
  | 'solid_mass'
  | 'cystic_lesion'
  | 'mixed_solid_cystic'
  | 'ductal_dilation_only'
  | 'incidentaloma';

export type SolidMassDifferential =
  | 'pancreatic_adenocarcinoma' // Most common
  | 'pancreatic_net' // Neuroendocrine tumor
  | 'autoimmune_pancreatitis' // Type 1 (IgG4) or Type 2
  | 'metastasis_to_pancreas'
  | 'lymphoma'
  | 'serous_cystadenoma'
  | 'unknown';

export type CysticLesionType =
  | 'ipmn_main_duct' // High malignancy risk
  | 'ipmn_branch_duct' // Lower risk
  | 'ipmn_mixed_type'
  | 'mucinous_cystic_neoplasm' // MCN — women, body/tail
  | 'serous_cystadenoma' // Benign
  | 'pseudocyst' // Post-pancreatitis
  | 'solid_pseudopapillary_neoplasm' // SPN — young women
  | 'unknown_cystic';

export type ResectabilityStatus =
  | 'resectable'
  | 'borderline_resectable'
  | 'locally_advanced'
  | 'metastatic'
  | 'not_assessed';

export interface PancreaticMassInput {
  // Mass characteristics
  massType: PancreaticMassType;
  massLocation: 'head' | 'body' | 'tail' | 'uncinate' | 'diffuse' | 'unknown';
  massSizeCm?: number;
  hasMainPancreaticDuctDilation: boolean;
  mainPDDiameterMm?: number; // ≥5mm = high-risk feature for IPMN
  hasSolidComponent: boolean;
  hasEnhancingMuralNodule: boolean; // High-risk IPMN feature
  hasBileDuctDilation: boolean;
  hasVascularInvolvement: boolean;
  hasLymphadenopathy: boolean;
  hasDistantMetastases: boolean;

  // Clinical context
  hasJaundice: boolean;
  hasWeightLoss: boolean;
  hasAbdominalPain: boolean;
  hasNewOnsetDiabetes: boolean; // New-onset DM in elderly = pancreatic cancer risk
  hasAcutePancreatitis: boolean;
  hasChronicPancreatitis: boolean;

  // Tumor markers
  ca199?: number; // >37 U/mL = elevated; >1000 = likely malignant
  cea?: number;
  igg4?: number; // >135 mg/dL = autoimmune pancreatitis

  // Prior workup
  hasCTScan: boolean;
  hasMRIPancreas: boolean;
  hasERCP: boolean;
  hasEUSPerformed: boolean;
  eusFindingsDescription?: string;
  hasTissueAcquired: boolean;
  tissueResult?: 'malignant' | 'suspicious' | 'atypical' | 'benign' | 'non_diagnostic' | 'pending';

  // Cystic lesion specific
  cysticType: CysticLesionType;
  cystSizeCm?: number;
  hasWorrisomeFeatures: boolean; // IPMN: cyst >3cm, thickened wall, MPD 5–9mm, non-enhancing mural nodule, abrupt MPD change
  hasHighRiskStigmata: boolean; // IPMN: obstructive jaundice, enhancing mural nodule, MPD ≥10mm

  // Resectability
  resectabilityStatus: ResectabilityStatus;
  hasSMAInvolvement: boolean; // Superior mesenteric artery
  hasCeliacInvolvement: boolean;
  hasSMVPVInvolvement: boolean; // Superior mesenteric/portal vein

  // Patient factors
  ageYears: number;
  performanceStatus: 'good' | 'moderate' | 'poor'; // ECOG 0–1, 2, 3–4
  isSurgicalCandidate: boolean;
}

export interface PancreaticMassRecommendation {
  primaryRecommendation: string;
  diagnosticWorkup: string;
  eusStrategy: string;
  tissueAcquisitionApproach: string;
  molecularDiagnostics: string;
  cysticLesionManagement: string;
  resectabilityAssessment: string;
  multidisciplinaryPlan: string;
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessPancreaticMass(input: PancreaticMassInput): PancreaticMassRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasJaundice && input.hasBileDuctDilation) {
    urgentFlags.push('OBSTRUCTIVE JAUNDICE: biliary decompression may be required before resection — ERCP/EUS-BD vs percutaneous drainage. Urgent GI/surgery consultation.');
  }
  if (input.hasHighRiskStigmata) {
    urgentFlags.push('HIGH-RISK IPMN STIGMATA (obstructive jaundice, enhancing mural nodule, MPD ≥10mm): surgical resection recommended without delay — high malignancy risk');
  }
  if (input.hasDistantMetastases) {
    urgentFlags.push('Distant metastases: pancreatic cancer is metastatic — systemic chemotherapy discussion (FOLFIRINOX or gemcitabine/nab-paclitaxel). Palliative care consultation.');
  }
  if (input.ca199 !== undefined && input.ca199 > 1000) {
    urgentFlags.push(`CA 19-9 ${input.ca199} U/mL (>1000): very high likelihood of pancreatic adenocarcinoma — expedite tissue acquisition and oncology referral`);
  }
  if (input.hasNewOnsetDiabetes && input.ageYears > 50 && input.massType === 'solid_mass') {
    urgentFlags.push('New-onset diabetes in patient >50 with pancreatic mass: high suspicion for pancreatic adenocarcinoma — expedite workup');
  }

  // ─── Diagnostic Workup ────────────────────────────────────────────────────
  let diagnosticWorkup = '';
  if (!input.hasCTScan && !input.hasMRIPancreas) {
    diagnosticWorkup =
      'IMAGING REQUIRED before EUS: ' +
      '1) CT pancreas protocol (triple-phase): preferred for resectability assessment and vascular involvement. ' +
      '2) MRI/MRCP: preferred for cystic lesions, biliary anatomy, and IPMN characterization. ' +
      '3) Both CT and MRI/MRCP are complementary — CT for vascular anatomy, MRI for soft tissue/cystic detail.';
    nextSteps.push('CT pancreas protocol (triple-phase) for resectability assessment', 'MRI/MRCP for cystic lesion characterization');
  } else if (input.hasCTScan && !input.hasMRIPancreas && input.massType === 'cystic_lesion') {
    diagnosticWorkup = 'MRI/MRCP recommended for cystic lesion characterization — superior to CT for duct communication, mural nodules, and IPMN features.';
    nextSteps.push('MRI/MRCP for cystic lesion characterization');
  } else {
    diagnosticWorkup = 'Cross-sectional imaging performed. Proceed with EUS for tissue acquisition and detailed characterization.';
  }

  // ─── EUS Strategy ─────────────────────────────────────────────────────────
  let eusStrategy = '';
  if (input.massType === 'solid_mass' || input.massType === 'mixed_solid_cystic') {
    eusStrategy =
      'EUS-GUIDED TISSUE ACQUISITION for solid pancreatic mass (ASGE 2024): ' +
      '1) EUS provides real-time imaging + tissue acquisition in a single procedure. ' +
      '2) EUS-FNB (fine needle biopsy) is PREFERRED over FNA (ASGE 2024 Strong Recommendation): ' +
      '   - FNB needles (Franseen, Fork-tip, ProCore): provide core tissue for histology + IHC. ' +
      '   - Superior for: neuroendocrine tumors, autoimmune pancreatitis, lymphoma, metastases. ' +
      '   - Diagnostic yield: 85–95% with FNB vs 75–85% with FNA. ' +
      '3) Rapid on-site evaluation (ROSE) by cytopathologist: improves diagnostic yield when available. ' +
      '4) Approach: transgastric (body/tail), transduodenal (head/uncinate). ' +
      '5) Avoid transgastric approach if surgical resection planned (theoretical seeding risk — controversial).';
  } else if (input.massType === 'cystic_lesion') {
    eusStrategy =
      'EUS for cystic pancreatic lesion (ASGE 2024): ' +
      '1) EUS provides detailed morphology: mural nodules, septa, wall thickness, duct communication. ' +
      '2) EUS-FNA of cyst fluid: indicated for worrisome features or diagnostic uncertainty. ' +
      '   - Cyst fluid analysis: CEA >192 ng/mL = mucinous (MCN or IPMN). ' +
      '   - Amylase: high = pseudocyst or IPMN with duct communication. ' +
      '   - Cytology: low sensitivity but high specificity for malignancy. ' +
      '3) Molecular analysis (Cologuard-type cyst fluid DNA): KRAS/GNAS mutation + VHL mutation. ' +
      '   - KRAS/GNAS: mucinous cyst (IPMN/MCN). VHL: serous cystadenoma. ' +
      '4) EUS-guided through-the-needle biopsy (TTNB): emerging — forceps biopsy of cyst wall.';
  } else {
    eusStrategy = 'EUS indicated for further characterization. Approach depends on final mass type and location.';
  }

  // ─── Tissue Acquisition Approach ─────────────────────────────────────────
  let tissueAcquisitionApproach = '';
  if (!input.hasTissueAcquired) {
    tissueAcquisitionApproach =
      'TISSUE ACQUISITION STRATEGY (ASGE 2024): ' +
      '1) EUS-FNB with 22G or 25G Franseen or Fork-tip needle (preferred over FNA for solid masses). ' +
      '2) Pass count: 2–3 passes with FNB (vs 5–7 with FNA) — fewer passes needed. ' +
      '3) Fanning technique: sample multiple areas of the mass to improve yield. ' +
      '4) ROSE (rapid on-site evaluation): use if available — reduces inadequate samples. ' +
      '5) For cystic lesions: aspirate cyst fluid completely, send for CEA, amylase, cytology, and molecular analysis. ' +
      '6) If EUS-FNB non-diagnostic: repeat EUS-FNB or consider CT-guided biopsy (if surgically unresectable).';
    nextSteps.push('EUS-FNB (fine needle biopsy) with 22G Franseen or Fork-tip needle', 'Send tissue for: H&E histology, IHC (CK7, CK20, synaptophysin, chromogranin, IgG4), molecular testing');
  } else if (input.tissueResult === 'non_diagnostic') {
    tissueAcquisitionApproach =
      'Non-diagnostic prior tissue acquisition: ' +
      '1) Repeat EUS-FNB with different needle type (Franseen vs Fork-tip). ' +
      '2) Increase pass count or use ROSE. ' +
      '3) Consider CT-guided biopsy if EUS access suboptimal. ' +
      '4) If clinically high suspicion for malignancy: proceed to surgery without tissue confirmation (resectable disease).';
    nextSteps.push('Repeat EUS-FNB with alternative needle type', 'Consider multidisciplinary tumor board review');
  } else {
    tissueAcquisitionApproach = `Tissue acquired — result: ${input.tissueResult}. Proceed with management based on pathology.`;
  }

  // ─── Molecular Diagnostics ────────────────────────────────────────────────
  const molecularDiagnostics =
    'MOLECULAR DIAGNOSTICS (ASGE 2024 — integration with tissue acquisition): ' +
    '1) Solid mass: ' +
    '   - Next-generation sequencing (NGS): KRAS, TP53, SMAD4, CDKN2A — diagnostic + prognostic. ' +
    '   - BRCA1/2, PALB2 germline testing: 5–7% of pancreatic cancer — actionable (PARP inhibitors, platinum). ' +
    '   - MSI/MMR testing: rare in pancreatic cancer but actionable (pembrolizumab). ' +
    '   - NTRK fusion, RET fusion: rare but highly actionable (larotrectinib, selpercatinib). ' +
    '2) Cystic lesion fluid: ' +
    '   - KRAS/GNAS mutation: mucinous cyst (IPMN/MCN) — high specificity. ' +
    '   - VHL mutation: serous cystadenoma. ' +
    '   - TP53/SMAD4/CDKN2A: high-grade dysplasia or malignancy in mucinous cyst. ' +
    '   - CEA >192 ng/mL: mucinous cyst. ' +
    '3) Liquid biopsy (ctDNA): emerging — not yet standard of care for initial diagnosis.';

  // ─── Cystic Lesion Management ─────────────────────────────────────────────
  let cysticLesionManagement = 'Not applicable — solid mass.';
  if (input.massType === 'cystic_lesion' || input.massType === 'mixed_solid_cystic') {
    if (input.hasHighRiskStigmata) {
      cysticLesionManagement =
        'HIGH-RISK IPMN STIGMATA: surgical resection recommended (AGA/ASGE 2024). ' +
        'High-risk features: obstructive jaundice, enhancing mural nodule, MPD ≥10mm. ' +
        'Pancreaticoduodenectomy (Whipple) for head/uncinate; distal pancreatectomy for body/tail. ' +
        'Surgical oncology referral urgently.';
      nextSteps.push('Surgical oncology referral for pancreatic resection', 'Preoperative staging CT + MRI/MRCP');
    } else if (input.hasWorrisomeFeatures) {
      cysticLesionManagement =
        'WORRISOME IPMN FEATURES: EUS evaluation recommended (AGA 2024). ' +
        'Worrisome features: cyst >3cm, thickened/enhancing wall, MPD 5–9mm, non-enhancing mural nodule, abrupt MPD change, lymphadenopathy. ' +
        'EUS-FNA with cyst fluid analysis (CEA, amylase, cytology, molecular). ' +
        'If EUS confirms high-risk features: surgical resection. ' +
        'If no high-risk features on EUS: close surveillance (MRI/MRCP every 3–6 months).';
      nextSteps.push('EUS with cyst fluid aspiration and molecular analysis', 'Multidisciplinary pancreatic cyst program review');
    } else if (input.cysticType === 'mucinous_cystic_neoplasm') {
      cysticLesionManagement =
        'MUCINOUS CYSTIC NEOPLASM (MCN): surgical resection recommended for all fit patients (AGA 2024). ' +
        'MCN has malignant potential (10–15% harbor invasive carcinoma). ' +
        'Distal pancreatectomy (body/tail location). ' +
        'Surgical oncology referral.';
      nextSteps.push('Surgical oncology referral for MCN resection');
    } else if (input.cysticType === 'serous_cystadenoma') {
      cysticLesionManagement =
        'SEROUS CYSTADENOMA: benign — surveillance only. ' +
        'Resection only if symptomatic or >4cm with rapid growth. ' +
        'MRI/MRCP every 2 years.';
    } else if (input.cysticType === 'pseudocyst') {
      cysticLesionManagement =
        'PANCREATIC PSEUDOCYST: drainage if symptomatic (pain, infection, compression). ' +
        'EUS-guided cyst drainage with LAMS (lumen-apposing metal stent) — preferred over surgical or percutaneous drainage. ' +
        'Asymptomatic pseudocysts: observe — many resolve spontaneously.';
    } else {
      cysticLesionManagement =
        'Cystic lesion of uncertain type: MRI/MRCP + EUS for characterization. ' +
        'Cyst fluid analysis (CEA, amylase, cytology, molecular) to determine mucinous vs non-mucinous. ' +
        'Surveillance interval based on size and features.';
    }
  }

  // ─── Resectability Assessment ─────────────────────────────────────────────
  let resectabilityAssessment = '';
  if (input.massType === 'solid_mass' || input.tissueResult === 'malignant') {
    if (input.resectabilityStatus === 'resectable') {
      resectabilityAssessment =
        'RESECTABLE: upfront surgery recommended (NCCN 2025). ' +
        'Pancreaticoduodenectomy (Whipple) for head/uncinate; distal pancreatectomy for body/tail. ' +
        'Adjuvant chemotherapy: modified FOLFIRINOX (mFOLFIRINOX) x6 months post-resection (PRODIGE 24 trial). ' +
        'High-volume pancreatic surgery center preferred (lower mortality).';
      nextSteps.push('Surgical oncology referral at high-volume pancreatic center', 'Preoperative staging: CT chest/abdomen/pelvis + CA 19-9');
    } else if (input.resectabilityStatus === 'borderline_resectable') {
      resectabilityAssessment =
        'BORDERLINE RESECTABLE: neoadjuvant chemotherapy ± radiation recommended before surgery (NCCN 2025). ' +
        'FOLFIRINOX x4–6 months → restaging CT → surgery if downstaged. ' +
        'Multidisciplinary tumor board review required. ' +
        'Biliary stenting if jaundiced (SEMS preferred over plastic stent).';
      nextSteps.push('Multidisciplinary pancreatic tumor board', 'Neoadjuvant FOLFIRINOX chemotherapy', 'Biliary stenting if jaundiced');
    } else if (input.resectabilityStatus === 'locally_advanced') {
      resectabilityAssessment =
        'LOCALLY ADVANCED (unresectable): systemic chemotherapy ± radiation. ' +
        'FOLFIRINOX or gemcitabine/nab-paclitaxel. ' +
        'SBRT (stereotactic body radiation therapy) for local control. ' +
        'Biliary and/or gastric outlet decompression as needed.';
    } else if (input.resectabilityStatus === 'metastatic') {
      resectabilityAssessment =
        'METASTATIC: systemic chemotherapy. ' +
        'FOLFIRINOX (fit patients, ECOG 0–1) or gemcitabine/nab-paclitaxel. ' +
        'BRCA1/2 mutation: platinum-based chemotherapy + olaparib maintenance (POLO trial). ' +
        'MSI-H: pembrolizumab. ' +
        'Palliative care consultation.';
    } else {
      resectabilityAssessment = 'Resectability not yet assessed — CT pancreas protocol required.';
    }
  }

  // ─── Multidisciplinary Plan ───────────────────────────────────────────────
  const multidisciplinaryPlan =
    'MULTIDISCIPLINARY TEAM (MDT) APPROACH (NCCN 2025 — required for all pancreatic masses): ' +
    '1) Gastroenterology/interventional endoscopy: EUS, tissue acquisition, biliary drainage. ' +
    '2) Surgical oncology: resectability assessment, pancreatic surgery. ' +
    '3) Medical oncology: chemotherapy planning (neoadjuvant/adjuvant/palliative). ' +
    '4) Radiation oncology: SBRT for locally advanced disease. ' +
    '5) Radiology: imaging interpretation, CT/MRI staging. ' +
    '6) Pathology: tissue diagnosis, molecular profiling. ' +
    '7) Palliative care: symptom management, goals of care. ' +
    '8) Genetic counseling: germline testing (BRCA1/2, PALB2, ATM, Lynch syndrome).';

  if (nextSteps.length === 0) {
    nextSteps.push(
      'CT pancreas protocol (triple-phase) for resectability assessment',
      'MRI/MRCP for biliary anatomy and cystic lesion characterization',
      'EUS-FNB for tissue acquisition',
      'CA 19-9, CEA, IgG4 serum markers',
      'Multidisciplinary pancreatic tumor board referral',
      'Genetic counseling for germline testing (BRCA1/2, PALB2)'
    );
  }

  const rationale =
    `Mass type: ${input.massType.replace(/_/g, ' ')}. ` +
    `Location: ${input.massLocation}. ` +
    `Size: ${input.massSizeCm ? `${input.massSizeCm}cm` : 'not measured'}. ` +
    `Cystic type: ${input.cysticType.replace(/_/g, ' ')}. ` +
    `High-risk stigmata: ${input.hasHighRiskStigmata ? 'Yes' : 'No'}. ` +
    `Tissue acquired: ${input.hasTissueAcquired ? `Yes (${input.tissueResult})` : 'No'}. ` +
    `Resectability: ${input.resectabilityStatus.replace(/_/g, ' ')}.`;

  return {
    primaryRecommendation:
      input.hasHighRiskStigmata
        ? 'HIGH-RISK IPMN: surgical resection recommended — surgical oncology referral urgently.'
        : input.hasDistantMetastases
        ? 'Metastatic pancreatic cancer: systemic chemotherapy (FOLFIRINOX or gemcitabine/nab-paclitaxel) + palliative care.'
        : !input.hasTissueAcquired && input.massType === 'solid_mass'
        ? 'Solid pancreatic mass: EUS-FNB (fine needle biopsy) preferred over FNA for tissue acquisition (ASGE 2024).'
        : input.massType === 'cystic_lesion' && !input.hasHighRiskStigmata && !input.hasWorrisomeFeatures
        ? 'Cystic pancreatic lesion without high-risk features: MRI/MRCP surveillance per lesion type and size.'
        : 'Pancreatic mass evaluation: multidisciplinary team approach with EUS, cross-sectional imaging, and tissue acquisition.',
    diagnosticWorkup,
    eusStrategy,
    tissueAcquisitionApproach,
    molecularDiagnostics,
    cysticLesionManagement,
    resectabilityAssessment,
    multidisciplinaryPlan,
    urgentFlags,
    nextSteps,
    evidenceLevel: 'B',
    rationale,
    references: [
      {
        citation: 'ASGE Standards of Practice Committee. The role of endoscopy in the evaluation and management of patients with solid and cystic pancreatic lesions. Gastrointest Endosc. 2024.',
        url: 'https://www.asge.org/home/guidelines-quality/guidelines-standards/guidelines-standards-detail/the-role-of-endoscopy-in-the-evaluation-and-management-of-patients-with-solid-and-cystic-pancreatic-lesions',
      },
      {
        citation: 'Elta GH, et al. ACG Clinical Guideline: Diagnosis and Management of Pancreatic Cysts. Am J Gastroenterol. 2018;113(4):464-479.',
        pmid: '29485131',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29485131/',
      },
      {
        citation: 'Conroy T, et al. FOLFIRINOX or Gemcitabine as Adjuvant Therapy for Pancreatic Cancer (PRODIGE 24). N Engl J Med. 2018;379(25):2395-2406.',
        pmid: '30575490',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30575490/',
      },
      {
        citation: 'Gonda TA, et al. Molecular Classification and Biomarkers of Clinical Outcome in Pancreatic Cysts. Gastroenterology. 2021;160(5):1718-1732.',
        pmid: '33454340',
        url: 'https://pubmed.ncbi.nlm.nih.gov/33454340/',
      },
    ],
  };
}
